ATL_SRC.push(['@atl/elxsplit.js', 0, `// Two-week (or longer) Electrolit Billing Activity files (Nov 2026, from Josh: "split by week"). Such a file still goes
// to the Electrolit scorecard's Billing drop, and its lines are also split by date into weeks (Sun–Sat) and posted to
// Customer Throughput — one entry per week, with that week's pallets in / out, loads, the rail / truck split and the
// ship-to history — so the dashboards, KPI reports and Customer History have it. Same rules as Customer History's
// history drop: each load counts once (by BL #) in the week of its date.
//  - A week not posted yet: added.
//  - A week already posted: replaced with the file's numbers when the file covers that whole week (it has lines from
//    the week's Monday or earlier); when the file starts part-way through the week, only missing loads / rail-truck
//    fields are filled in, so a partial week never overwrites a complete one.
import { store } from '@atl/store.js';
import { derive } from '@atl/calc.js';
import { isISO, weekEnding, addDays } from '@atl/util.js';
import { readBillingFile, toThroughput, weekThroughput, shipToDocs } from '@atl/billing.js';
import { saveShipTos } from '@atl/views/customers.js';

const LOAD_KEYS = ['loadsIn', 'loadsOut', 'loadsInPrev', 'loadsOutPrev', 'mtIn', 'mtOut', 'palletsIn', 'palletsOut', 'railIn', 'truckIn', 'railSkidsIn', 'truckSkidsIn', 'truckLoadsIn', 'railCarsIn'];
const blank = v => v === undefined || v === null || v === '';

/** What posting these files to Customer Throughput would do: [{ we, c, loads, doc, act: New | Replace | Fill | Same, out }]. */
export async function splitPlan(files) {
  const customers = store.settings.throughputCustomers || [], seen = new Map(), firstDay = new Map();
  for (const file of files) {
    const parsed = await readBillingFile(file);
    for (const f of toThroughput(parsed, customers)) f.allLoads.forEach((l, j) => {
      const we = isISO(l.date) ? weekEnding(l.date) : parsed.week; if (!we) return;
      seen.set(\`\${f.c.building}|\${f.c.name}|\${l.dir}|\${l.bl || \`\${file.name}#\${j}\`}\`, { c: f.c, we, l });
      if (isISO(l.date)) { const k = \`\${we}|\${f.c.building}|\${f.c.name}\`; if (!firstDay.has(k) || l.date < firstDay.get(k)) firstDay.set(k, l.date); }
    });
  }
  const groups = new Map();
  for (const x of seen.values()) { const k = \`\${x.we}|\${x.c.building}|\${x.c.name}\`; const g = groups.get(k) || { we: x.we, c: x.c, loads: [] }; g.loads.push(x.l); groups.set(k, g); }
  const have = new Map();
  for (const r of derive('throughput')) { const k = \`\${r.weekEnding}|\${r.building}|\${r.customer}\`; if (!have.has(k)) have.set(k, store.rows('throughput').find(x => x.id === r.id) || r); }
  return [...groups.values()].sort((a, b) => a.we.localeCompare(b.we)).map(g => {
    const k = \`\${g.we}|\${g.c.building}|\${g.c.name}\`, doc = weekThroughput(g.c, g.we, g.loads), old = have.get(k);
    const wholeWeek = (firstDay.get(k) || g.we) <= addDays(g.we, -5); // lines from the week's Monday (or earlier)
    let act, out = null;
    if (!old) { act = 'New'; out = doc; }
    else if (wholeWeek) { act = 'Replace'; out = { ...old, ...doc, id: old.id }; }
    else { const add = Object.fromEntries(LOAD_KEYS.filter(f => f in doc && blank(old[f])).map(f => [f, doc[f]])); act = Object.keys(add).length ? 'Fill' : 'Same'; if (act === 'Fill') out = { ...old, ...add, id: old.id }; }
    if (out) { const { total, weeknum, ...clean } = out; out = clean; }
    return { ...g, doc, act, out };
  });
}
/** Post the plan: Customer Throughput weeks and their ship-to history. Returns the number of weeks written. */
export async function postSplit(plan) {
  const docs = plan.filter(p => p.out).map(p => p.out);
  for (let i = 0; i < docs.length; i += 400) await store.writeMany('throughput', docs.slice(i, i + 400));
  for (const p of plan.filter(p => p.act !== 'Same')) await saveShipTos(p.we, { [\`\${p.c.building}|\${p.c.name}\`]: shipToDocs({ week: p.we }, p.c, p.loads.filter(l => l.dir === 'Out')) });
  return docs.length;
}`]);

